const EFC_MANUAL_SECTIONS = [
    { id: 'systems', tag: 'SYSTEM DIRECTORY', title: 'THE Echelon STACK', intro: 'The systems currently supporting Echelon. Use the secure access directory in your password manager for the actual credentials.', cards: [
        ['Echelon Website', 'Public site', 'https://www.echelonfitness.co', 'Use for public pages, coaching applications, waitlist, and member access.'],
        ['GitHub', 'Source control', 'https://github.com/echelonfitnesscollective-ctrl/ECHELON_LIVE', 'The live site source. Every approved update is recorded here and triggers the Vercel deployment.'],
        ['Vercel', 'Hosting & deployments', 'https://vercel.com/dashboard', 'Hosts echelonfitness.co. Review the fresh deployment after every approved update.'],
        ['Supabase', 'Members, forms, admin data & site content', 'https://supabase.com/dashboard/project/plkdyvtriajpzcfgtwzp', 'Source of truth for member data, check-ins, goals, plans, messages, photos, the Admin Console, published Site Content, and the public Media Gallery.'],
        ['Resend', 'Owner notification emails', 'https://resend.com/', 'Sends an email to echelonfitnesscollective@gmail.com the moment any public form is submitted (coaching application, contact, free class, partnerships, check-in, waitlist). Requires a RESEND_API_KEY set in Vercel.'],
        ['Formspree', 'Message-your-coach relay', 'https://formspree.io/', 'Still used for the in-portal "message your coach" notification only. Form submissions are now emailed via Resend instead.'],
        ['Stripe', 'Payments & enrollment checkout', 'https://dashboard.stripe.com/', 'Processes secure group fitness and approved-coaching payments. Keep Stripe in test mode until the full applicant-to-invite flow has been tested once.'],
        ['Google Calendar', 'Session scheduling sync', 'https://calendar.google.com/', 'Connected from the Admin Console SESSIONS tab. Native booking (1-on-1, corporate groups, drop-in Group Fitness) lives entirely in the site’s own booking tables now; Calendly is no longer used.'],
        ['Google Business Profile', 'Reviews & discovery', 'https://business.google.com/', 'Manage business details, verification, and the link used in Echelon review-request messages.'],
        ['Instagram', 'Social channel', 'https://www.instagram.com/EchelonFitness.co', 'Primary social presence and community touchpoint.'],
        ['TikTok', 'Social channel', 'https://tr.ee/pO3gLtovXy', 'Short-form content and discovery channel.'],
        ['Etsy', 'Merch storefront · planned', '', 'Keep the shop placeholder until the Etsy shop is ready. Then add the Etsy URL in one place.'],
        ['Amway', 'Performance nutrition', 'https://www.amway.com/', 'Use only the approved product links and disclosure language already placed on the Echelon shop.']
    ]},
    { id: 'daily-ops', tag: 'DAILY OPERATIONS', title: 'THE DAILY COMMAND ROUTINE', steps: [
        ['Open the Today tab', 'Start in the Admin Console on Today. Clear overdue Coach Command tasks and create any new task that requires a next action.'],
        ['Review members and leads', 'Move to Members for active coaching activity, then Leads for new applications, contact requests, and waitlist entries.'],
        ['Follow up with intent', 'Create a task for every lead or member action that needs a next step. Give it a due date and priority.'],
        ['Close the loop', 'Mark completed tasks done and leave a private coach note for context the next time you return.']
    ]},
    { id: 'console-tabs', tag: 'ADMIN CONSOLE MAP', title: 'USE ONE FOCUSED TAB AT A TIME', intro: 'The Admin Console is intentionally organized as a horizontal tab workspace. Only the selected tab is visible, so operators can focus on one kind of work without losing their place.', steps: [
        ['Today', 'Your daily command center. Review priorities, clear Coach Command tasks, and create the next action for anything that needs follow-through.'],
        ['Members', 'Open member records, onboarding details, and recent check-ins. Use this tab for active coaching context and member-care decisions.'],
        ['Leads', 'Review coaching applications first, then contact and waitlist inquiries. Send the appropriate response and create a Coach Command task before moving on.'],
        ['Programs', 'Open an offering’s collapsible playbook for its delivery steps. All 5 program-operation cards (Free Class, Echelon 12, 1-on-1 Coaching, Faith & Favor Mobility, VL Body Lab) now include their completed coach PDF, each with its own Echelon-branded cover.'],
        ['Site Content', 'Create announcements, offers, resource releases, storefront notes, and calls to action without code. Drafts stay private; Published items display immediately; Scheduled items go live automatically; expiry dates remove items automatically.'],
        ['Media', 'Manage the public Echelon gallery. Upload a quality photo or short video, add the label and caption, set its display order, then publish it. To replace a frame, upload the new version first and remove the old version only after you see the new one live.'],
        ['Comms', 'Use the collapsed Response Library categories for approved scripts. Open only the situation you need, copy it, personalize every bracketed detail, then send.'],
        ['Library', 'Manage the member vault and private trainer resources. Use this for publishing guides and storing coach education, not for daily follow-ups.'],
        ['Equipment', 'Internal inventory only, not member-facing. Track what you own (name, category, price, quantity, condition, purchase date) and keep a running note thread per item for repairs, reorders, or condition changes.'],
        ['Workout Library', 'Build the reusable coaching building blocks in order: Exercises (rich detail: form cues, coaching cues, up/down/pregnancy modifications, video link) → Workouts (assemble published exercises with sets/reps/rest, and set whether it is a Gym, Mobile, or Both session) → Program Templates (assign workouts to a week/day grid for a 12-week base model). An exercise or workout must be Published before it can be added to the next layer up or assigned to a member.'],
        ['Coaching Playbook', 'Read-only reference library: every base program, group-format blueprint, process template, and per-goal education + delivery-format guide (78 documents across all 6 goal categories) in one searchable, browsable tab. Content is edited in the codebase (docs/coaching-programs/, docs/education/), not through a form; this tab just makes it easy to find and read without digging through files.'],
        ['Sessions', 'The native scheduler: create and edit recurring availability windows (day, time, session type, capacity, class name, 1-on-1 appointment length), generate a one-off group join link for a corporate or drop-in class, and view the month calendar of everyone booked, including who is on a waitlist. This is where every capacity/label/waitlist rule below is actually set and changed, no code involved.']
    ]},
    { id: 'offerings', tag: 'TRAINING HUB', title: 'RUN A FOCUSED OFFERING STACK', intro: 'The public Training Hub now presents six distinct programs. Keep Faith & Favor Mobility and VL Body Lab as their own cards; they are not one combined future-program offering. Launch a program only when its staff coverage, delivery plan, and calendar capacity are real.', steps: [
        ['Group Fitness · live', '$23 drop-in or $89/month unlimited. Use a fixed, published session schedule. Active 12-Week and 1-on-1 Hybrid clients are included; one class each month is free and open to the public.'],
        ['Private Group Training · now booking', 'For 3–15 people: friends, families, teams, organizations, celebrations, or wellness sessions. Start at $199 for up to five participants, then $25 per additional participant. Offer one-time or recurring groups only in designated event windows.'],
        ['Echelon 12 · live', 'A structured 12-week coaching system. Use the completed Echelon 12 Coach Playbook, then publish Week 1, nutrition baseline, and the check-in cadence after payment and onboarding.'],
        ['1-on-1 Coaching · live', 'Limited, high-touch coaching. Approval is required. Release only the windows you can honor around your Burn schedule and Echelon capacity.'],
        ['Faith & Favor Mobility · in development', 'A 45-minute small-group mobility, posture, core-stability, and active-recovery class. Keep it on the interest list until coverage and a sustainable recurring slot are confirmed.'],
        ['VL Body Lab · in development', 'A 50-minute strength, speed, and athletic-conditioning group experience. Keep it on the interest list until coverage and a sustainable recurring slot are confirmed.']
    ]},
    { id: 'new-lead', tag: 'LEAD FLOW', title: 'WHEN A NEW LEAD COMES IN', steps: [
        ['Find the lead', 'Open Coaching Applications or Contact & Waitlist in the Admin Console.'],
        ['Create the next action', 'Add a Coach Command follow-up task with their name, a due date, and the correct priority.'],
        ['Respond personally', 'Use your approved contact method. Update your private note with the important context and outcome.'],
        ['Move forward or close out', 'Keep the task open until there is a real next step. Mark it complete once the handoff or decision is final.']
    ]},
    { id: 'accepted-applicant', tag: 'ACCEPTED APPLICANT FLOW', title: 'FROM APPLICATION TO ACTIVE MEMBER', intro: 'The Admin Console now turns an approval into a clear, trackable handoff. Payment happens privately through Stripe; the Member Portal invitation only unlocks after Stripe confirms it.', steps: [
        ['Applicant submits', 'Resend emails echelonfitnesscollective@gmail.com the application notification and Supabase saves the record. A NEW MEMBER LAUNCH project and its private checklist are created automatically.'],
        ['Coach reviews', 'Open Leads → Coaching Applications. Read the application, select the aligned program and payment choice, then choose Create Payment Link. The checklist marks the review, program choice, and payment-link handoff complete.'],
        ['Applicant pays', 'Use Copy Payment Link and Open Payment Email to send the applicant their private Stripe link. They see only their coaching selection and complete secure Stripe checkout. Do not collect card details yourself.'],
        ['Stripe confirms', 'Stripe records the completed payment, changes the application to Paid: Ready to Invite, and completes the payment-verification step in the launch checklist. A failed or expired payment link stays inactive.'],
        ['Admin activates access', 'Return to that application and select Invite to Member Portal. Supabase sends the member a secure password/setup email and grants their active Member Portal access.'],
        ['Coach launches', 'Finish the remaining launch tasks: confirm onboarding and waiver, publish Week 1, set the check-in cadence, and confirm launch readiness. The member then sees their focused Coaching Hub first.']
    ]},
    { id: 'calendar', tag: 'SCHEDULING OPERATIONS', title: 'PROTECT YOUR COACHING WINDOWS', intro: 'Echelon scheduling is built to work around the coach’s Burn shifts instead of pretending there is unlimited availability. Booking links are private and should show only confirmed Echelon windows.', notice: 'Calendly is not activated until its three unlisted event URLs are added to assets/js/calendar-config.js. Until then, the Echelon Scheduling page intentionally tells clients that their approved booking link will be sent by Echelon.', steps: [
        ['Build the availability source', 'In Calendly, connect both the Burn-shift calendar and the Echelon calendar. Let busy events block availability automatically. Create one unlisted event each for 1-on-1 coaching, Private Group Training, and discovery calls.'],
        ['Set real rules', 'Use a minimum 24-hour notice, buffers before and after sessions, a daily session limit, and only the time blocks you can coach consistently. Reserve designated event windows for private groups.'],
        ['Activate the links', 'Paste the three Calendly URLs into assets/js/calendar-config.js: oneOnOneUrl, privateGroupUrl, and discoveryCallUrl. Commit the update to GitHub main and confirm Vercel shows a Ready production deployment.'],
        ['Send links at the right moment', 'For 1-on-1: after approval and payment. For Private Group Training: after the organizer is approved, payment or deposit is confirmed, and group details are aligned. For discovery calls: after a qualified inquiry needs a live conversation.'],
        ['Use the scheduling page', 'Send the appropriate /pages/booking.html?type= link rather than a raw Calendly URL when possible. It keeps the Echelon context, explains availability rules, and opens the matching private booking action once activated.'],
        ['Review each week', 'Compare the coming week against Burn commitments, active clients, group events, and recovery time. Close or adjust Calendly windows before they become a conflict.']
    ]},
    { id: 'communication', tag: 'COMMUNICATION STANDARD', title: 'HOW ECHELON RESPONDS', intro: 'The Response Library in the Admin Console is the approved starting point for every outreach moment. It keeps the language warm, clear, and consistent while leaving space for a real personal reply.', notice: 'Never paste credentials, health details, payment details, or a member’s private information into an email, text, or public message. Do not guarantee a fitness outcome or provide medical advice. Use the Medical / High-Risk Question script when a concern falls outside coaching scope.', steps: [
        ['Acknowledge quickly', 'For contact requests, coaching applications, waitlist entries, and check-ins, send the matching acknowledgment immediately or as soon as you see it.'],
        ['Personalize before sending', 'Replace every bracketed detail, read the full message, and give one clear next step. Never send a template untouched.'],
        ['Track the promise', 'If you say you will reply, schedule, review, or follow up, create a Coach Command task with a due date before leaving the conversation.'],
        ['Use the right channel', 'Email is the record for leads, onboarding, and decisions. Portal messaging is for active-member coaching. Social DMs should move to email or the application form when personal details are needed.'],
        ['Close the loop', 'After the person responds or the next action is complete, add the outcome to the relevant member or lead note and mark the Coach Command task complete.']
    ]},
    { id: 'member-care', tag: 'MEMBER FLOW', title: 'WHEN A MEMBER JOINS', steps: [
        ['Create secure access', 'Create or invite the member through Supabase Authentication, then direct them to the Member Portal.'],
        ['Complete readiness', 'Confirm onboarding intake and the Echelon waiver are complete before training begins.'],
        ['Build their program', 'Open their member record (Members tab, click their name) and scroll to COACHING HUB. Use the "Program Enrollment" mini-form: pick a published 12-week program template and a start date, click ENROLL IN PROGRAM. That one click generates their entire Today\'s Work calendar for the full 12 weeks automatically, including a deload note at week 6 if the program has one. Nothing else to send, the member sees it themselves in their Member Portal Coaching Hub. Use the "Assign a Single Day" form underneath only for one-off changes (swap a single day, or a client not on a full program).'],
        ['Check or edit a program\'s plan', 'Workout Library tab → Program Templates → click any program to open its calendar editor. The progression guide (how load/reps/rest change week to week, when the deload week falls, what the Progress Review covers) shows at the top before the week/day list. This is coach-facing planning reference, members never see it directly, their Today\'s Work just reflects it.'],
        ['Set the rhythm', 'Ask for weekly check-ins, review their momentum, and use private messages for timely support.']
    ]},
    { id: 'member-portal', tag: 'MEMBER EXPERIENCE', title: 'WHAT MEMBERS SEE FIRST', intro: 'The Member Portal is arranged around the member’s current coaching rhythm rather than a long menu of links. Direct a member to the first relevant action instead of asking them to search.', steps: [
        ['Coaching Hub first', 'This is the member&apos;s primary daily space: Today&apos;s Work (their next two weeks of assigned sessions: sets/reps, what each exercise targets, form and coaching cues, any modifications, and whether it&apos;s a gym or mobile session), nutrition log, progress photos, and private coach messaging. A legacy freeform plan panel still shows underneath for any member with an older-style plan on file.'],
        ['Session Check-In next', 'Use when they are preparing for an in-person session or need to signal readiness to the coach.'],
        ['Weekly Performance', 'Use for the structured weekly review of progress, habits, recovery, and coaching focus.'],
        ['Vault and Resource Hub', 'The Member Vault holds private Echelon material. The Resource Hub provides the broader education and complimentary resources.'],
        ['First-Time Setup last', 'Onboarding and waiver are intentionally collapsed at the bottom. They must be complete before training begins, but they do not distract active members after setup.']
    ]},
    { id: 'publishing', tag: 'WEBSITE UPDATES', title: 'HOW TO PUBLISH AN UPDATE', steps: [
        ['Use Site Content for daily changes', 'For announcements, temporary offers, class notices, resource releases, shop messages, or a focused button, use the Site Content tab in the Admin Console. It publishes directly from Supabase. No code, GitHub, or Vercel step needed.'],
        ['Choose the right placement', 'Homepage places the update before About. Training, Resources, and Shop place it at the top of that specific section. Keep one strong message per placement whenever possible.'],
        ['Set the life cycle', 'Save unfinished copy as Draft. Choose Published for immediate visibility or Scheduled for a future go-live time. Add an end time for anything temporary so it removes itself automatically.'],
        ['Refresh the media gallery', 'Use the Media tab to upload photos or short MP4/WebM videos for the carousel. Publish only approved media, use low display-order numbers for priority frames, and remove retired frames after their replacement is confirmed.'],
        ['Work locally first', 'Make changes in the Echelon website folder and review them in your browser.'],
        ['Publish through GitHub', 'Commit the approved website changes to the ECHELON_LIVE main branch. Vercel automatically creates the production deployment.'],
        ['Review the deployment', 'Open Vercel after the GitHub update and confirm the production deployment is ready. The live domain then receives the new version.'],
        ['Verify live essentials', 'Test the home page and all six Training Hub cards, a form, member login, admin login, password reset, a member-prefilled check-in, and the booking page on echelonfitness.co.']
    ]},
    { id: 'access', tag: 'CREDENTIAL DIRECTORY', title: 'SECURE ACCESS, NOT SHARED PASSWORDS', notice: 'Do not store passwords, recovery codes, or payment details in this website or in the Admin Console. Keep them in a dedicated password manager and grant each operator their own access.', steps: [
        ['Password manager record', 'For each system above, store the sign-in URL, account owner, recovery contact, 2FA method, and emergency recovery instructions.'],
        ['Individual access only', 'Invite each operator to Vercel, Supabase, Resend, Formspree, and Etsy using their own email whenever that platform supports it.'],
        ['Handoff checklist', 'Before someone operates alone, have them complete a preview deployment, review a test lead, create a test task, and send a test member message.'],
        ['Offboarding', 'Remove their access from each system and your password manager as soon as their role ends.']
    ]},
    { id: 'overhaul-2026-07', tag: 'CHANGE LOG', title: 'SITE OVERHAUL: WHAT CHANGED', intro: 'A full site pass covering launch blockers, conversion, design, security, and compliance. Everything below is live in production. Keep this section until the next major update.', steps: [
        ['Pricing is now public', '12-Week Transformation shows "$399 paid in full, or $149/month." 1-on-1 Coaching shows "$399/month" flat. Both are hardcoded in index.html\'s Training Hub cards; update the text directly there if pricing changes.'],
        ['1-on-1 scarcity line is manual', 'The "Accepting up to 6 new 1-on-1 clients this month" line near the 1-on-1 card is plain text in index.html, not pulled from the roster automatically. Update it by hand as your actual capacity changes.'],
        ['Waiver now blocks Member Hub access', 'Member Portal, Coaching Hub, Nutrition, Performance, and the Member Vault all check for a signed member_waivers row before loading. A member with account access but no signed waiver is redirected to the waiver page automatically. Nothing to check manually.'],
        ['Member Login is in every header', 'Previously footer-only. Now a small "Member Login" link sits in the header nav (and mobile menu) on the homepage and every public page.'],
        ['Standardize on "VL Body Lab"', 'Never use "VL Kinetic" in new copy, forms, or Formspree routing labels. It was a naming inconsistency that has been fully corrected site-wide.'],
        ['Shop link is a single variable', 'EFC_ETSY_SHOP_URL at the top of assets/js/shop-showcase.js controls the "Shop the Collection" button. Leave it blank for the current "Notify Me" waitlist state, or set your real Etsy URL there once the storefront is live. One change updates the whole site.'],
        ['Conversion tracking is wired but inactive', 'assets/js/analytics.js fires events for drop-in purchase, coaching application, private group inquiry, waitlist join, and check-in completion, but only once a GA4 Measurement ID is installed. It is currently a safe no-op.'],
        ['Scheduled backup is built but not yet running', 'scripts/backup/ exports member profiles, waivers, progress photos, coaching applications, and other critical tables to a Google Sheet + Drive folder daily via GitHub Actions, but needs a one-time Google Cloud service account setup before its first run. See scripts/backup/README.md.'],
        ['Security headers centralized', 'CSP, X-Frame-Options, and HSTS are all set in vercel.json. Contact and coaching application forms now go through rate-limited server routes (api/contact/submit.js, api/coaching-application/submit.js) instead of writing to Supabase directly from the browser.'],
        ['Legal pages contact info fixed', 'Privacy, Terms, and Disclaimer pages now list echelonfitnesscollective@gmail.com and www.echelonfitness.co (previously showed a placeholder domain that never matched the live site).'],
        ['Stripe catalog reviewed and fixed', '12-Week pay-in-full copy corrected to match the $399 Stripe price (was showing $349). Removed a stray duplicate price left on the Group Fitness product from initial setup.'],
        ['Private Group Training checkout now works', 'Previously had no working payment path at all. Now: base $199 (up to 5 people) + $25/person add-on price in Stripe; the admin Applications panel has a group-size field (3–15) that auto-calculates the total and sends a single payment link with both line items.'],
        ['First class free: no Stripe involved', 'New "Try your first class free" link on the Group Fitness card (pages/free-class.html) captures name/email/phone/preferred day into website_leads (lead_type "Free class request") for a coach to confirm and schedule, same pattern as the contact form, no payment step.'],
        ['Group Fitness purchases now show up for you', 'Previously a drop-in or unlimited purchase completed in Stripe but left zero record anywhere in the Admin Console. The webhook now logs each one into website_leads (lead_type "Group fitness purchase") so it shows up in your leads list like any other inquiry.'],
        ['Group Fitness pricing raised to market rate (2026-07-28)', 'Drop-in moved $20 → $23; Unlimited moved $59 → $89/month after checking local comps (a same-city competitor charges $125–213/mo for the same category of service). Old Stripe prices are archived, not deleted. Anyone already subscribed at $59/mo keeps billing at that rate forever unless you or they change it. That is the entire grandfather mechanism: Stripe never migrates an existing subscription to a new price on its own.'],
        ['12-Week Transformation never auto-ends', 'The $149/mo plan is an open-ended Stripe subscription by design. "12-week" names the coaching curriculum, not a billing cutoff. Nothing cancels automatically. When a 12-Week enrollment is paid, the webhook creates a Coach Command task ("12-Week check-in: [name]") due 84 days later so you have the renew/upgrade/move-to-Group conversation at the natural checkpoint instead of losing the client to a silent auto-cancellation.'],
        ['Section Control: edit the whole Training Hub without touching code (2026-07-29)', 'New "Section Control" panel inside Program Delivery (Training Hub → scroll down) replaces the old Launch Control. Every card (Group Fitness, Private Group Training, 12-Week, 1-on-1, Faith & Favor, VL Body Lab) now has editable Name, Subtitle, Description, and repeatable Program Detail rows that save straight to the public site, plus ▲/▼ buttons to reorder the cards. Faith & Favor, VL Body Lab, and a new blank "Special Event" slot additionally get a launch date (and an optional expires date for the event slot) to flip live or auto-hide with no code change or redeploy. Backed by a new training_programs Supabase table (RLS: public reads anything not hidden, only admins write). This replaces program_launches, which is left in place unused rather than deleted. Same recipe as everything else in this console: Supabase table + admin-only RLS + progressive-enhancement JS that leaves the static page untouched if the fetch ever fails. This is the pattern to reuse: table + RLS gate + public read policy + a JS file that fails safe, if you build another site and want the same "edit anything, break nothing" setup.'],
        ['B2B partnerships intake (2026-07-30)', 'New pages/partnerships.html pitches on-site weekly group fitness to apartment complexes/employers as a resident/employee amenity, with a "Request a Proposal" form (organization, contact, property size, on-site space, preferred day, message). Submissions post to api/partnerships/submit.js, which writes into the existing website_leads table with lead_type "Partnership Inquiry", so no new table was needed, and it shows up in the same Leads list on the Operations Console as every other inquiry. Linked from the homepage footer ("PARTNERSHIPS"), not the Training Hub carousel, since this is a property-manager/decision-maker pitch, not a consumer sign-up. Pricing is intentionally not shown on the page. It is a sales conversation, not a checkout; a printable one-pager with a placeholder pricing table exists separately for direct outreach and still needs real dollar figures filled in before it is sent to anyone.'],
        ['Security audit fixes (2026-07-30)', 'Three fixes from a static security review: (1) Deleted admin-portal.html and js/echelon-config.js: a leftover admin panel from an earlier version of the site, still publicly reachable, gated only by a fakeable localStorage flag, and pointing at a separate old Supabase project outside this system’s protection. (2) Turned on the missing privacy rule (RLS) for prospective_clients, onboarding_task_templates, and onboarding_task_template_items: prospective_clients holds real applicant names/emails/phones and was very likely publicly readable before this fix; now admin-only, same pattern as every other table. (3) The waitlist and check-in forms (pages/waitlist.html, pages/checkin.html) used to write straight from the browser to Supabase with the public key, with no rate limiting and no length caps. They now route through api/forms/submit.js (one shared endpoint, dispatched by a "form" field), matching every other public form on the site. Combined into one file instead of two separate ones because Vercel Hobby caps a deployment at 12 serverless functions. The first attempt at this fix briefly broke production with a "no more than 12 functions" build error; consolidating brought the count back to exactly 12 and redeployed clean. Still open from the same review: an old third-party Supabase project referenced by the deleted legacy panel needs its own lockdown/key rotation directly in that account, outside what this console can reach.'],
        ['Session timeout: Member Portal and Admin Console (2026-07-30)', 'Previously, once someone signed in, the session never expired on its own; only closing the browser tab required signing in again. Now, 15 minutes with no clicks, taps, scrolling, or key presses on any member page or in the Admin Console automatically signs that session out and returns to the login page with a "you were signed out" message. Any activity resets the clock, and a background check runs every 60 seconds so someone idle on a single page without navigating still gets signed out on schedule. This is a business-logic timeout layered on top of the existing tab-close protection; it does not affect the browser or phone\'s own saved-password/Face ID autofill, which still works normally the next time you sign in, it is just not treated as "still signed in" while you are away. Implemented once each in assets/js/member-auth.js\'s requireMemberSession() gate and assets/js/admin-auth.js\'s requireAdminSession() gate, so every member page and every admin page (Dashboard, Operations Manual) is covered automatically without touching each one individually.'],
        ['Coaching Content System: Equipment, Workout Library, Today\'s Work (2026-07-31)', 'New Admin Console tabs: Equipment (internal inventory tracking with price/quantity/condition and a per-item note thread, not member-facing) and Workout Library (three linked layers: Exercises with form cues, coaching cues, and up/down/pregnancy modifications; Workouts that assemble published exercises with sets/reps/rest; Program Templates that assign workouts to a 12-week week/day grid). The old freeform "PUBLISH TRAINING PLAN" box in a member\'s detail view is replaced by a real Today\'s Work assignment tool: pick a published workout, a date, an optional coach note, send. It inserts into a new member_daily_workouts table. Members see it in a new "TODAY\'S WORK" panel on the Coaching Hub: sets/reps, what each exercise targets, form and coaching cues, a collapsible modifications section, and a mark-complete action. The legacy freeform plan panel is untouched and still shows underneath for anyone with an older-style plan on file. Nothing was migrated or deleted. Backed by 8 new Supabase tables (RLS: admin-only on Equipment and Program Templates, admin-write with published-only member-read on Exercises/Workouts, admin-all with owner-read/owner-update-status-only on Today\'s Work). See database/supabase-coaching-content.sql. Six base 12-week program templates (Cutting, Weight Loss, Bulking, Muscle, Performance, Older-Adult Wellness) and structural blueprints for the four recurring/group cards (Group Fitness, Private Group Training, Faith & Favor Mobility, VL Body Lab) were drafted as reviewable documents in docs/coaching-programs/, not yet seeded into the Workout Library. Seed the approved ones in through the Equipment/Workout Library tabs when ready; nothing in this system auto-populates itself.'],
        ['Program Enrollment: plug-and-play Today\'s Work (2026-07-31)', 'Enrolling a member in a published program template (Coaching Hub → Enroll in Program: pick the template and a start date) now bulk-generates their entire Today\'s Work calendar in one action, computed from each program day\'s week_number/day_number offset from the start date. Nothing needs to be sent daily. A new member_program_enrollments table records who is on what program starting when (admin-write, member-read-own). The old per-day form still exists, relabeled "Assign a Single Day," for one-off personalization or clients not on a full program; both write to the same member_daily_workouts table, and the recent-assignments history now has a REMOVE button to clean up a wrong entry. Workouts also gained a Gym / Mobile (out of the car) / Both setting, shown in the Workout Library list, the single-day assignment picker, and (when not plain Gym) as a small badge on the member\'s Today\'s Work card, for mobile/hybrid clients coached out of a vehicle rather than a fixed gym. The member Today\'s Work panel now shows the next 14 days instead of 3, with the current day visually highlighted. database/supabase-mobile-plugandplay.sql (run once in the Supabase SQL Editor to activate all of this) also seeds a starter "Mobile Kit" equipment category (bands, TRX-style trainer, adjustable dumbbells/kettlebell, sandbag, jump rope, mats, foam roller, med balls, agility cones, timer, speaker, first aid kit, scale, calipers, tape measure; price and quantity intentionally left blank to fill in with real numbers) and fully seeds the Cutting 12-week base model into the Workout Library (29 exercises, 5 workouts, full 12-week calendar) as a working example of the new system end to end. The other 5 drafted base programs and 4 blueprints stay reviewable-only in docs/coaching-programs/ pending approval.'],
        ['Client Training Profile intake (2026-08-01)', 'A member\'s intake detail view (Members tab) now includes a Training Profile section above the coaching controls: delivery setting, primary/secondary goal, age, training experience, training days available, session duration, equipment, current activity, injuries/conditions/medical clearance, exercise preferences, sleep and stress, and biggest consistency barrier. This is the same 14-field intake used to personalize which base program and delivery format actually fits a given client, backed by a new member_training_profiles table (RLS: admin manages all, member can report their own). See database/supabase-training-profile.sql (run once in the Supabase SQL Editor to activate it).'],
        ['Coaching Playbook made permanent, education and delivery-format guides drafted for all 6 goals (2026-08-02)', 'Every base program, group-format blueprint, process template, and per-goal education + delivery-format guide (78 documents total) was reviewed and approved. What that unlocked: a new read-only "Coaching Playbook" tab in the Admin Console (see Console Tabs above) is now the permanent home for browsing all 78 documents, replacing the temporary review link. Education and delivery-format guides (Group / 1-on-1 / 12-Week / VL Body Lab / Mobility tailoring) now exist for all 6 goal categories: Weight Loss, Cutting, Bulking, Muscle (Hypertrophy), Performance, and Older-Adult Wellness, not just Weight Loss. Each guide is written around the same 14-field client intake captured in the new Training Profile (above), so a plan can be genuinely personalized rather than handed out as one generic template.'],
        ['Free education live on the public Resource Hub for all 6 goals (2026-08-03)', 'The public Resource Hub (pages/resources.html) "Free Starter Library" now has a nav pill and 3 free articles for every goal category, not just Weight Loss: Weight Loss, Cutting, Bulking, Muscle, Performance, and Older-Adult (18 free articles total). No admin action needed, this content is already live.'],
        ['Remaining 5 base programs seeded into the Workout Library (2026-08-03)', 'Cutting was the first program seeded end to end as a working example (see the 2026-07-31 entry above). The other 5 base programs (Weight Loss, Bulking, Muscle, Performance, Older-Adult Wellness) now have a matching seed file ready: database/seed-remaining-programs-workout-library.sql. Run it once in the Supabase SQL Editor to populate their exercises, workouts, and full 12-week calendars into the live Workout Library tab, the same way Cutting already works. It is safe to re-run (every insert is idempotent).'],
        ['Resource Hub rebuilt: only-what-you-click shows, downloadable watermarked PDFs (2026-08-03)', 'The public Resource Hub (pages/resources-hub.html) had grown into one long flat page where all 21 articles could expand open at once, with a legacy dead tab system still sitting underneath it, and a real layout bug where opening one card in a 2-column grid left ragged blank space next to it. It is now a clean tab system: 15 category pills grouped into Quick-Start Tools, Fuel by Goal, and Goal Library, each showing a compact preview grid, and clicking a card opens ONE focused reading panel with everything else on the page untouched underneath. Every article (except the two meal-guide images) now has a matching branded, watermarked "FREE RESOURCE" PDF download button right in that reading panel. All original article wording was preserved exactly, byte-for-byte, verified before the rebuild shipped.'],
        ['Fuel articles per goal + training-split education added to the free library (2026-08-03)', 'New "FUEL BY GOAL" section in the Resource Hub: one substantial article per goal (Weight Loss, Cutting, Bulking, Muscle, Performance, Older-Adult Wellness) that walks a reader through calculating their own BMR (Mifflin-St Jeor formula, with a fully worked numeric example), turning that into a daily calorie target (TDEE), and adjusting it for that specific goal, plus a plain-language macro framework and a trainer-scope mention of XS™ Whey Protein and XS™ Creatine+ linking to the Echelon Goods shop. The Training category also grew from one thin card to five: the original "3-Part Starter" plus four new articles explaining Full-Body, Push/Pull/Legs, and Upper/Lower training splits, and a practical "how to actually choose one" decision guide tied to Echelon\'s own Bulking (upper/lower) and Muscle (PPL) base programs. All 10 new pieces have matching free-tier PDFs like everything else in the library.'],
        ['Member Vault now shows free guides plus EXCLUSIVE premium resources, in one place (2026-08-03)', 'The Member Vault (pages/member-library.html) used to be a single flat list pulled only from admin-uploaded files. It now shows the exact same category-tabbed view as the public Resource Hub, every free guide included, with any admin-uploaded premium resource (Library tab → Publish to Member Vault) inserted into its matching goal category and tagged EXCLUSIVE / MEMBER ONLY so members can tell what is unique to being a member. The Library upload form\'s category field changed from free text to a dropdown (Weight Loss / Cutting / Bulking / Muscle / Performance / Older-Adult Wellness / Fuel / Training / General) so every future upload groups correctly without relying on typed text matching. The 18 premium PDFs generated earlier are ready to upload through that form whenever you are.'],
        ['Member Vault: premium content reads inline, personalized to each member\'s goal (2026-08-05)', 'Premium Library uploads used to be download-only links. The Member Vault reading modal now shows a PDF in an inline viewer (or an image directly) with a download button still underneath, using a signed Supabase Storage URL, no separate app or download step required to read something on the spot. Required adding frame-src for the Supabase storage domain to the CSP in vercel.json since the default policy blocks cross-origin framing. The vault also now reads each signed-in member\'s primary_goal from member_training_profiles and automatically opens on that member\'s own goal tab (with a small "YOUR GOAL" flag on the matching nav pill) instead of always defaulting to Fuel. Every other category is still one click away; nothing is hidden from anyone.'],
        ['Operations Console: application details are readable, payment links stop vanishing (2026-08-05)', 'Coaching applications collect 17 detailed fields (goal, timeline, barriers, support system, sleep, nutrition rating, and more), but the admin Leads list never displayed any of it and never even fetched it from Supabase. A new VIEW DETAILS toggle on each application now shows every populated field plus any private coach note. Separately, the "payment link vanishing" bug: creating a payment link would show the COPY/EMAIL buttons for an instant, then a background list refresh (triggered from inside the same success handler) would reset that application back to a fresh "CREATE PAYMENT LINK" state, discarding the only in-memory copy of the real Stripe URL. Fixed by removing that redundant refresh and making the link durably re-fetchable from enrollment_offers, so it survives a page reload too, not just the moment after creation. A related bug where clicking create could render two stacked sets of COPY/EMAIL buttons in the same card (harmless visually, confusing in practice) is also fixed: the render function now always clears any previous button pair before adding a new one.'],
        ['Stripe checkout: two dead price IDs found and fixed (2026-08-05)', '1-on-1 Hybrid Coaching checkout was failing with a generic "we could not begin checkout" error. Root cause: STRIPE_PRICE_ONE_ON_ONE_MONTHLY in Vercel had a one-character typo (missing a "b") pointing at a price ID that did not exist. Once checkout.js was updated to actually log Stripe\'s real rejection reason server-side instead of swallowing it, the typo was found by cross-referencing the price ID Stripe actually has on file for the product against what was stored in Vercel, then corrected and redeployed. The same method then turned up a second, unrelated dead price: STRIPE_PRICE_12_WEEK_FULL (the "$399 paid in full" option) pointed at a price ID that Stripe reports as fully nonexistent, not a typo, likely a leftover from before the current price catalog was set up. Also corrected and redeployed. The other price variables (12-Week monthly, both Private Group Training prices, Group drop-in, Group Unlimited) were each individually checked against Stripe and confirmed already correct.'],
        ['Brand Ambassador coupon: ECHELONCOREUNIT26 (2026-08-05)', 'A 100%-off, applies-forever coupon capped at 6 total redemptions, for handing out to brand ambassadors and for your own live testing. Confirmed working end to end on a real checkout session. Redemptions are a permanent record in Stripe once a real purchase completes; if the cap is ever tightened up again, delete and recreate the coupon under the same code rather than trying to edit the used-count, Stripe has no reset for that.'],
        ['Branded welcome email and page for new members (2026-08-05)', 'The email a paying member received after being invited to the Member Portal was Supabase\'s bare, unbranded default ("You\'ve been invited... Accept invitation"), and the password-set page that followed had no content on it either. Connected Resend as a custom SMTP provider for Supabase Auth (DNS records verified at Namecheap for echelonfitness.co), which unlocked full control over the email\'s subject and body, now a real Echelon-branded "Welcome to Echelon" email sending from welcome@echelonfitness.co. Also added a new pages/member-welcome.html: first-time invite links (detected via the auth link\'s type=invite, distinct from an ordinary forgot-password reset) now route through a personalized welcome page with the member\'s name, their program, and concrete next steps, before continuing into the Member Portal. Ordinary password resets are unaffected and still go straight to the portal.'],
        ['Section Control: hide any Training Hub card without touching its content (2026-08-05)', 'Every card in Section Control (Training Hub → scroll down) now has a HIDE FROM SITE / SHOW ON SITE button next to Save. It only ever flips the status field, so hiding a live program and bringing it back later never touches its name, description, or launch date. This also surfaced and fixed a real pre-existing bug: #training .training-card sets display:flex in main.css, which silently overrode the browser\'s default [hidden] behavior, so the special-event slot\'s "stay hidden until published" state, and now this new toggle, never actually removed a card from the page even though the hidden attribute was being set correctly. An explicit #training .training-card[hidden]{display:none!important} rule fixes both.'],
        ['Fix a misspelled name, email, or phone on an application (2026-08-05)', 'Every coaching application now has a small pencil icon next to its Program · Email line. Click it to reveal a compact inline Name / Email / Phone form, fix the typo, and hit SAVE. Saves straight to coaching_applications and updates the visible name/email on the record immediately, no need to open VIEW DETAILS.'],
        ['Fix set-password page showing both forms at once (2026-08-06)', 'The Set Your Password page had the request-a-link form and the create-a-new-password form visible at the same time, a site-wide CSS rule for .echelon-form was silently overriding the hidden attribute, the same bug class already fixed once for the Training Hub cards. Added the matching CSS override so hidden forms actually stay hidden.'],
        ['Redesign Member Vault premium content viewer (2026-08-06)', 'Premium PDFs were embedded directly in the resource popup, which renders as a plain white page and often gets cut off in mobile or in-app browsers (like the one inside Gmail). The popup now matches the free resource guides exactly: the full article reads inline in the dark themed card, with a DOWNLOAD RESOURCE button at the bottom, no more raw PDF embed. All 18 premium articles were converted from their source drafts into this format.'],
        ['Replace the browser tab icon with the real Echelon logo (2026-08-06)', 'Every page now shows the actual gold Echelon "EC" mark as its tab icon (favicon) and home-screen icon, replacing the old placeholder mark. Covers all 26 real pages site-wide, not just the homepage.'],
        ['Fix the link preview image (2026-08-06)', 'When the site link is shared by text or social media, the preview image was an almost-invisible white ghost logo. It now shows a proper branded image of the homepage: the gym photo from the hero section with the Echelon logo overlaid.'],
        ['Redesign the Training Hub as one ecosystem, not four competing offers (2026-08-06)', 'Added a short intro line above the four core training cards framing them as a single path: Group Fitness (entry point) into 12-Week Transformation (signature program) into 1-on-1 Coaching (highest-touch, premium), with Private Group Training called out as a separate track for organizations. Updated each card\'s short description to match, and gave Private Group Training the subtitle "For Organizations and Groups" so it reads clearly apart from the individual progression. Changed in both index.html and the live training_programs table, so the copy matches whether or not Section Control data loads.'],
['Reframe 12-Week Transformation as coaching, not a class (2026-08-06)', '12-Week Transformation never had a class time to begin with, but the copy read like one. The card, its detail panel, and the live training_programs row now describe what a client actually gets: an assigned workout, nutrition guidance, weekly check-ins, progress photos, and community, delivered through the Member Portal all week, plus one shared group workout everyone attends together. The summary link changed from "+ View Session Details" to "+ View Program Details" to match. Pricing is unchanged.'],
['Add a Calendar tab to the Admin Console (2026-08-06)', 'The weekly 12-Week Transformation group workout does not have a fixed day or time yet, so a new CALENDAR tab (after Coaching Playbook) lets you paste in an embeddable Google Calendar or Notion link and preview it live in the console before sharing it anywhere. Backed by a new admin-only console_calendar_settings table (a single row, no member-facing read access). Google Calendar and Notion were added to the site\'s content security policy so the embedded preview actually renders instead of failing silently.'],
['Reprice Group Fitness, retire "unlimited" (2026-08-06)', 'Drop-in is now $20 (was $23) and the monthly membership is $79 (was $89), capped at 3 scheduled sessions per week instead of unlimited access, with a free community session every two weeks (was monthly). New Stripe prices were created and archived the old ones (no members were on the $89 plan, so no grandfathering was needed). The 3x/week cap is a stated policy only, there is no booking system to enforce it. Updated in Stripe, the homepage, and the live training_programs table.'],
['Launch Coaching Membership, the post-12-Week continuation tier (2026-08-06)', 'New $149/month Echelon Coaching Membership product in Stripe. This sits between Group Fitness and 1-on-1 Coaching as what a 12-Week Transformation graduate moves into: personalized programming, nutrition adjustments, weekly accountability, priority messaging. It is intentionally not a public homepage card, a cold visitor does not need to see it. Instead, the Members tab now has a "GENERATE CHECKOUT LINK" button on each member\'s Coaching Hub section, it hits the same public checkout endpoint used for Group Fitness and returns a real Stripe Checkout URL you copy and send directly, no new application flow needed.'],
['Turn the week-12 reminder into a real Progress Review script (2026-08-06)', 'The automatic coach_tasks reminder created the moment a 12-Week payment lands now fires at week 10 instead of week 12 (still nothing auto-cancels, this is just an earlier heads-up), and its description is now an actual script instead of a bare reminder: pull the client\'s progress photos and weekly check-in history from the Coaching Hub, then present the 3 ways to continue (Group Fitness $79/month, Coaching Membership $149/month, 1-on-1 Coaching $399/month) and use the new checkout-link button for whichever they pick.'],
['Align the Training Hub cards on a shared grid (2026-08-06)', 'The card title, subtitle, description, and "+ VIEW DETAILS" row now reserve the same fixed height on every card, so a one-line title (Group Fitness) and a two-line title (12-Week Transformation) still leave "+ VIEW DETAILS" landing on the same horizontal line across the whole row, whether or not a card has a scarcity tag like the 1-on-1 card\'s note. The "+ VIEW DETAILS" label itself also now reserves 2 lines, so a longer label like "+ View Group Experience Details" wrapping to a second line no longer pushes that one card taller than its neighbors. Every card\'s outer frame also now matches Group Fitness\'s height (the tallest, since it has two buttons plus a link instead of one), so no card\'s border sticks out below the row even though the buttons inside sit at different depths. Opening one card\'s details still only grows that one card, it does not stretch the rest of the row to match. The 1-on-1 scarcity note is now "Accepting up to 7 new 1-on-1 clients this month" and reads as a small italic aside instead of a bordered badge.'],
['Fix Hide From Site not actually hiding a Training Hub card (2026-08-06)', 'Clicking Hide From Site in Section Control set the card to hidden correctly in the database, but the public site never actually hid it, and it sometimes appeared stuck at the front of the row instead. The cause: the database\'s public-read rule refused to send a hidden row to the website at all, so the page\'s script never received it and could not hide it or place it correctly. The rule now sends every row and lets the existing on-page logic do the actual hiding, which is where it was designed to happen. Hide From Site now works as intended.'],
['Add a 7th program category: Pregnancy, in three stages (2026-08-06)', 'Three new base programs in the Workout Library, alongside the existing Cutting/Bulking/Muscle/Performance/Older-Adult/Weight Loss six: Preconception, Prenatal, and Postpartum. Preconception and Prenatal repeat a flat weekly pattern like the other six. Postpartum is genuinely phased and does not repeat: Phase 1 (breath and pelvic floor only, begins after medical clearance from her provider, not on a fixed calendar), Phase 2 (gentle core rebuild plus walking), Phase 3 (gradual return to full-body strength, gated by pelvic floor symptoms, not just time). Added 10 new pelvic floor, breathing, and pregnancy-safe movement exercises to the library to support this (diaphragmatic breathing, pelvic floor contractions, cat-cow, side-lying work, heel slides, and more), none of them existed before. The pregnancy-safe modification field is set from the Members tab Training Profile only, a coach decision made during an actual conversation, a member never sees a pregnancy toggle on her own dashboard.'],
        ['Add free and premium Pregnancy education content, 3 stages x 2 tiers (2026-08-07)', 'Pregnancy now has the same free-plus-premium education layer as the other six goal categories. Resource Hub (public) gained a PREGNANCY tab with 3 free articles, one per stage: preconception training fundamentals, what actually changes during prenatal training (and what does not), and why the postpartum return does not run on a fixed calendar. Each has a downloadable branded PDF, same as every other free article. The Member Vault gained 3 matching premium articles with the coaching-level detail: a step-by-step preconception training buildout, trimester-by-trimester prenatal programming, and the full phased postpartum return with the specific checkpoints that clear each phase to advance. All 6 pieces carry the same medical-deferral language as the rest of the pregnancy content, always defer to her provider\'s actual clearance.'],
        ['Add a hidden pink login easter egg (2026-08-07)', 'Typing "lulu" as the email and "melon" as the password on the member login page shows a full-screen pink tribute instead of attempting a real sign-in, any other combination goes through the normal sign-in flow untouched. Purely a personal touch on the member login page, no account or database involved.'],
        ['Write the 1-on-1 Coaching structural blueprint (2026-08-07)', 'Group Fitness already had a session-structure blueprint, 1-on-1 did not, it only had per-goal personalization guides. The new blueprint-05-one-on-one-coaching.md covers what those guides did not: cadence (2 in-person sessions/week, same Today\'s Work system as 12-Week on the days between), in-session shape (check-in, warm-up, main block, wrap-up), how live customization actually differs from 12-Week\'s pre-built modification fields, and a recurring 8-week Progress Review checkpoint since 1-on-1 has no fixed end date to force one. Registered in the Coaching Playbook manifest alongside the other blueprints.'],
['Build welcome-pack PDFs for all 7 base programs (2026-08-07)', 'A branded, 2-page welcome packet for each of the 7 base programs (Cutting, Bulking, Muscle, Performance, Older-Adult Wellness, Weight Loss, Pregnancy), meant to be handed to a client the day they enroll. Each covers: a short welcome note, a phase-by-phase program-at-a-glance table (Pregnancy\'s covers all 3 stages, Preconception/Prenatal/Postpartum, since your coach assigns whichever one actually fits the client), how Today\'s Work and check-ins work, what makes that specific program different from the other six, and the Echelon Standard closer. New WELCOME PACKETS group in the Coaching Playbook, each entry has a DOWNLOAD PDF button alongside the readable markdown source.'],
['Write Pregnancy base program docs and delivery-format guides (2026-08-07)', 'The 3 Pregnancy base programs (Preconception, Prenatal, Postpartum) existed only in the database, unlike the other 6 goals, they never had a documented base-program page. Added all 3, pulled directly from the live workout/exercise data, plus the 5 delivery-format guides (Group Fitness, 1-on-1, 12-Week Transformation, VL Body Lab, Faith and Favor Mobility) explaining how each stage actually plays in each format. The important calls: VL Body Lab is appropriate for Preconception but redirects away from Prenatal and Postpartum entirely (plyometric and sprint work does not belong in either). Faith and Favor Mobility is one of the best fits in the whole system for Prenatal and early Postpartum specifically. 12-Week Transformation should not auto-enroll a Postpartum client into the full 12-week calendar the way every other program does, phase advancement has to be manually confirmed against her actual symptoms, not the calendar. New Pregnancy goal group in the Coaching Playbook, plus the 3 base programs now appear alongside the other 6 in Base 12-Week Programs.'],
['Upload the ISSA trainer toolkit and make it browsable (2026-08-07)', 'The trainer-resources storage bucket existed but was empty, no ISSA PDFs had actually been uploaded yet. Added all 19: the All Forms Booklet, PDTM interview and workout planner (fillable and print versions), Training and Cardio Guidelines by Purpose, the ISSA Exercise Cheat Sheet, Move With Purpose, the Movement Observation Guide, Training Variables At-A-Glance, and the 8 sample workout plans (General Health, Muscle Gain, Performance, Weight Loss, each at 30 and 60 minutes). The Trainer Resources tab under Library previously only displayed a resource_url as plain text, files could not actually be opened from the admin console. Fixed: a file resource now shows an OPEN FILE button that generates a fresh signed link on click, same pattern as the Member Vault, an external URL still just opens directly. The one thing deliberately left out: the full copyrighted ISSA Chapter 1-15 textbook PDFs, those are personal study reference only, not something to redistribute even inside a private admin tool.'],
['Turn Training Hub \"View Details\" into a popup instead of an inline expand (2026-08-07)', 'The 7 Training Hub cards used to expand in place (an accordion), which pushed the card taller and shifted everything below it. Replaced with the same click-to-open, click-out-to-close popup pattern already used on the Resource Hub cards: the button now opens a centered modal with that card\'s details, closes on the X, clicking outside, or Escape. Section Control still edits the same underlying content, nothing changed there, only how it\'s displayed.'],
        ['Security hardening pass: honeypots, RLS audit, tighter function grants (2026-08-09)', 'A full review of what an outside attacker could actually reach. Findings: no secrets in git, admin endpoints properly gated, Stripe webhook signature-verified, RLS confirmed enabled everywhere with the right admin-only policies (checked directly via Supabase\'s Security Advisor and pg_policies, not assumed). Two real fixes shipped: (1) every public lead form (contact, coaching application, free class, partnerships, checkin, waitlist) now has a hidden honeypot field, a filled value is silently dropped instead of written to the database, layered on top of the per-IP rate limiting that already existed. (2) primary_echelon_admin(), which returns your admin user ID, had EXECUTE granted to anon; revoked so only authenticated members and the server can call it, the "message your coach" feature (which needs it) is unaffected.'],
        ['New Client program workflow made repeatable, and installable to a phone (2026-08-09)', 'Built a second full client program (Lex: Hybrid Athlete Performance Program) using the reusable New Client template, which sharpened the template itself: every client program PDF now has a matching standalone webpage at pages/programs/<name>.html (black/gold, same design as the PDF, generated from the same HTML so they can never drift apart) plus its own PWA manifest, so a client can add their program to their phone\'s home screen like a real app. When a client\'s actual working weights aren\'t known at build time, the program now says "Establish Week 1, log in Hub" instead of a guessed number, real weight gets captured through the Hub\'s new load-tracking field (below) and becomes their baseline. The template doc (docs/coaching-programs/template-new-client-pdf-and-hub-setup.md) now also documents the exercise-library lookup workflow: check for existing exercises before writing new ones, the safe pattern for typing long SQL in the Supabase editor without corruption, and how to avoid duplicate-named-exercise bugs when linking workouts.'],
        ['Coaching Hub: load tracking, fire streaks, jump-to-any-day, trusted-device sessions (2026-08-10)', 'Several Coaching Hub upgrades from real usage feedback. Today\'s Work now has a Load (lb) field on every exercise, saved per member per day (new member_exercise_logs table), so "Establish Week 1" prescriptions become real tracked numbers over time. A fire-streak indicator (🔥) now shows in the Today\'s Work header, counting consecutive scheduled workout days where the member completed the workout AND logged macros AND logged water, all three, not just one. A new JUMP TO DAY calendar lets a member on week 20 jump straight to any date in their program (month-by-month navigation) instead of only stepping one day at a time through a rolling 14-day window; the day they land on also shows that date\'s logged macros and weight underneath the workout. Members were getting signed out mid-workout because the step-up session marker lived in sessionStorage, which mobile browsers routinely clear when a tab is backgrounded for even a few seconds (checking a timer, a text). Login now offers a "Trust this device" checkbox (checked by default): trusted devices keep their session in localStorage instead, survive backgrounding, and only sign out after a full hour of real inactivity; untrusted/shared devices keep the original 15-minute sessionStorage behavior. Also: the redundant TRAIN/EVOLVE/CONNECT teaser section at the top of the Coaching Hub was removed (it just repeated the panels below it and delayed reaching real content), the top hero banner was redesigned to match the site\'s established intro-banner style and verified on mobile, the Photo Timeline\'s wording was softened ("UPLOAD PRIVATE PHOTO" to "ADD PROGRESS PHOTO", clearer captions), and Today\'s Work now scrolls inside its own frame instead of pushing the Photos and Message Coach panels far down the page on a long workout day. Separately, the remaining she/her placeholder and confirm-dialog copy across the admin console (manual onboarding/waiver entry, archive/delete member, the program build prompt) was made gender-neutral.'],
        ['Coach playbook PDFs written for the remaining 4 programs (2026-08-17)', 'Free Class, 1-on-1 Coaching, Faith & Favor Mobility, and VL Body Lab now each have a complete coach playbook PDF, matching the Echelon 12 template (before/deliver/send/follow-up steps, same branded layout). All 5 program-operation cards in the Programs tab now open a real PDF instead of some showing a placeholder. The old, since-removed CALENDAR tab (a paste-in Google Calendar/Notion embed link) was also removed in the same pass: SESSIONS is the native scheduler and fully replaced its purpose.'],
        ['Playbook covers redesigned to the real Echelon brand mark (2026-08-17)', 'All 5 coach playbook PDF covers were replaced twice in quick succession: first with a black-gym-floor-texture-plus-white-EC-monogram design, then swapped again for the owner\'s own finished Canva covers once those were ready, first at Instagram-Story proportions, then at proper 8.5x11 Letter proportions to match the interior pages. The final 8.5x11 versions are what is live now.'],
        ['Class labels, editable PT appointment slots, and a 1-spot waitlist for both group classes and 1-on-1 PT (2026-08-17 to 2026-08-18)', 'Three linked scheduling upgrades, all editable from the SESSIONS tab, no redeploy needed to change any of it. (1) class_label: a standing window (and everything it produces: bookings, group join links, Google Calendar sync) can now carry a real name like "VL Body Lab" or "Echelon Strength" instead of showing the generic session-type label. (2) 1-on-1 windows now generate distinct back-to-back appointment slots (a start time + session length + how many appointments) instead of one shared start time several people could all claim; session length is a flat 60 minutes across every PT window. (3) Waitlist: once a group class or a specific PT appointment slot is full, exactly one more booking is accepted as status "waitlisted" instead of being rejected outright. If the confirmed booking at that time is later canceled, the oldest waitlisted booking auto-promotes to confirmed (the member sees it next time they check My Sessions; there is no promotion email yet, see Known Open Items). The public group-join-link flow (pages/join-group.html) was also fixed to offer the waitlist spot instead of hard-blocking once a class hits capacity, and to correctly tell a waitlisted guest they are on the waitlist rather than confirmed. See database/supabase-scheduling-class-labels-waitlist.sql and database/supabase-scheduling-pt-waitlist.sql.'],
        ['Live recurring windows created: 5 PT blocks + 3 group classes (2026-08-18)', 'The actual standing windows now live in SESSIONS: 1-on-1 PT Monday & Wednesday 9am-1pm (4 back-to-back 60-min appointments each) and Tuesday, Thursday & Friday 1-3:30pm (2 appointments each, with a buffer); plus 3 recurring group classes at capacity 20 (+1 waitlist spot each) -- Echelon Strength Tuesday 5pm, VL Body Lab Thursday 5pm, Faith & Favor Mobility Friday 5pm. See database/supabase-scheduling-live-windows.sql. Every day, time, capacity, session length, and class name here can be changed directly in SESSIONS without touching code.'],
        ['A window\'s time slots now follow its Training Hub program\'s live/hidden status (2026-08-18)', 'SESSIONS windows had no connection to Section Control: a window could show real bookable times even while its Training Hub card still said "In Development." Each window now has an optional "Linked program" dropdown (edit any window in SESSIONS to set it). Once linked, that window only produces bookable time slots on the member booking calendar while the linked program is actually LIVE on the site; flip the card to In Development or Hidden in Section Control and its time slots stop showing automatically, no need to touch the window itself. The 5 PT windows are linked to 1-on-1 Coaching (already live, no visible change) and the 3 group-class windows are linked to their matching card (Group Fitness, VL Body Lab, Faith & Favor Mobility). VL Body Lab and Faith & Favor Mobility still say "In Development" on the site as of this entry, so their real times are intentionally not yet visible to members, set a Launch Date on that card in Section Control when ready to actually open booking. An unlinked window is unaffected and always shows, exactly as before. See database/supabase-scheduling-program-link.sql.'],
        ['Coaching application questions are now admin-editable, plus a way to send them as a link (2026-08-25)', 'Added the "do you already have a current workout plan you like and follow" question to the Coaching Application, and, bigger, the whole profile/goal section of that application (fitness level, goals, barriers, lifestyle, coaching readiness, 16 questions total, now 17) is no longer hardcoded in the page. It is a new admin-editable question bank (LEADS tab, new APPLICATION QUESTIONS panel): add a question, edit its wording, mark it required, reorder it, or retire it, and it updates everywhere at once, both on the public application and on the new assigned-link flow below, no code change or redeploy. Also new: an ASSIGN ONBOARDING QUESTIONS button on both Coaching Applications and Site Inquiries rows. Click it and it generates a one-time private link you can text or email to someone you did not get on a call with; they answer the same question set on their own time at pages/onboarding-questions.html, no login needed, and it lands back in the Applications list exactly like a normal application, tagged VIA ASSIGNED LINK. See database/supabase-onboarding-questions.sql.'],
        ['Fixed a leftover gendered pronoun, a badge wrapping bug, and added waiver/onboarding resend reminders (2026-08-25)', 'The manual "ENTER WAIVER FOR THIS MEMBER" checkbox in a member\'s record still read "She verbally agreed", missed by the earlier gender-neutral pass, now reads "They". Also fixed a visual bug in the new APPLICATION QUESTIONS panel where a long question\'s ACTIVE/RETIRED badge would wrap into a vertical stack of single letters instead of staying on one line. Bigger addition: Member Records now has a RESEND WAIVER REMINDER button (shows when a member\'s waiver is not yet signed) and a RESEND ONBOARDING REMINDER button (shows when their PAR-Q/health onboarding is not yet done), right next to the existing manual phone/in-person entry forms. Either sends the member a real email with a link back into the Member Portal, which already knows to route them straight to whichever step is still outstanding.'],
['Member waiver/onboarding self-completion now emails you (2026-08-25)', "When a member signs their waiver or saves their onboarding themselves in the Member Portal, that always saved correctly and shows up in Member Records the next time you open it, that part was never broken. What was missing: unlike every other form on the site (new application, new lead, an assigned onboarding link being completed), nothing told you it happened. You had to already be looking at that member's record to notice. Both pages now also send you a short email the moment it's saved, same as everything else."],
        ['Scheduling: fixed a broken program-link migration, added every-other-week classes, new Group Fitness schedule, Private Group cap raised to 25 (2026-08-25)', "Found and fixed a real bug while making these changes: the SQL migration that links a standing availability window to its Training Hub program (so a window only shows once its program is actually live) had been written and the admin Sessions code already depended on it, but the migration itself had never actually been run, so that column silently did not exist. Fixed, and while in there also found and deactivated 5 duplicate/orphaned Group Fitness window rows (some were live and bookable despite showing no real class name). Bigger addition: the scheduler only understood a plain weekly repeat before this. Windows can now repeat every N weeks (recurrence_interval_weeks + recurrence_anchor_date, editable in SESSIONS same as everything else), which is what powers the new Group Fitness schedule: Monday and Thursday 6-7pm every week, plus Saturday 8-9am every other week starting 2026-09-05 (so Sept 5 runs, Sept 12 is off, Sept 19 runs, and so on). Also raised the Private Group Training cap from 15 to 25 people site-wide (checkout validation, admin group-size field, and all card/application copy), groups larger than 25 still need to be arranged directly."],
        ['1-on-1 Coaching now has 3 ways in: Starter session and 20-session pack added alongside Monthly (2026-08-26)', 'Monthly ($399/month) used to be the only 1-on-1 payment option. Two new one-time Stripe prices were added: a $55 Starter Session (try it once) and a $950 20-Session Pack. Both are selectable from the payment-option dropdown when creating an offer for an approved 1-on-1 applicant, right alongside Monthly. Monthly\'s framing was also tightened: it is unlimited scheduling access for the month, not a bundle of sessions, so it reads clearly next to the two session-based options now sitting beside it. Updated on the 1-on-1 Coaching card\'s Investment detail on the site and in the database.'],
        ['Members can now edit their own Coaching Profile after they join (2026-08-26)', 'Until now, the Coaching Application answers (fitness level, goals, barriers, lifestyle, coaching readiness) were frozen the moment someone applied, there was no way for a client to update them later without you manually editing their record. A new member_profile_answers table now carries those same answers forward as a live, ongoing profile: seeded automatically from their original application the moment they are invited as a member, then editable any time by the member from a new COACHING PROFILE section in the Member Portal (right next to Account Settings), and by you from the same COACHING PROFILE (SELF-EDITABLE) section already in Member Records, right under Training Profile. Both sides render the exact same admin-editable question bank (APPLICATION QUESTIONS), so if you add, edit, or retire a question there, it updates on both the public application and this ongoing profile automatically. See database/supabase-member-profile-answers.sql.'],
        ['Known open items', 'Waitlist confirmation/promotion email (needs a Formspree autoresponder or email API you set up -- applies to both the general interest waitlist and the new session-booking waitlist auto-promotion), a lapsed-member re-engagement flow (flagged, not built, needs your sign-off), real price/quantity numbers for the seeded Mobile Kit equipment, running database/seed-remaining-programs-workout-library.sql to activate the 5 remaining base programs in the Workout Library, Pregnancy education content (6 free/premium articles) does not have markdown source docs in the Coaching Playbook the way every other goal\'s education content does, and Lex\'s nutrition_profiles targets (set from his actual 193 lb / 5\'11" stats) will need updating when he moves from Build phase into the Cut phase around Week 17.']
    ]}
];

function manualElement(tag, text, className) { const el = document.createElement(tag); if (text) el.textContent = text; if (className) el.className = className; return el; }

function renderManualSection(section) {
    const article = manualElement('section', '', 'manual-section'); article.id = section.id;
    article.append(manualElement('span', section.tag, 'checkin-tag'), manualElement('h2', section.title));
    if (section.intro) article.append(manualElement('p', section.intro, 'manual-intro-copy'));
    if (section.notice) article.append(manualElement('p', section.notice, 'manual-security-notice'));
    if (section.cards) { const grid = manualElement('div', '', 'manual-system-grid'); section.cards.forEach(([name, type, url, description]) => { const card = manualElement('article', '', 'manual-system-card'); card.append(manualElement('span', type), manualElement('h3', name), manualElement('p', description)); if (url) { const link = manualElement('a', 'OPEN SYSTEM →'); link.href = url; link.target = '_blank'; link.rel = 'noopener'; card.append(link); } else card.append(manualElement('em', 'Link to be added when Etsy launches.')); grid.append(card); }); article.append(grid); }
    if (section.steps) { const list = manualElement('ol', '', 'manual-steps'); section.steps.forEach(([title, copy], index) => { const item = manualElement('li'); item.append(manualElement('span', String(index + 1).padStart(2, '0')), manualElement('strong', title), manualElement('p', copy)); list.append(item); }); article.append(list); }
    return article;
}

document.addEventListener('DOMContentLoaded', async () => {
    const root = document.getElementById('admin-operations-manual'); if (!root) return;
    const admin = await requireAdminSession(); if (!admin) return;
    document.getElementById('manual-session').textContent = admin.email || 'Echelon Administrator';
    document.getElementById('manual-updated-on').textContent = new Intl.DateTimeFormat(undefined, { month: 'long', day: 'numeric', year: 'numeric' }).format(new Date());
    const content = document.getElementById('manual-content'); const index = document.getElementById('manual-index-links');
    EFC_MANUAL_SECTIONS.forEach(section => { content.append(renderManualSection(section)); const link = manualElement('a', section.title); link.href = `#${section.id}`; index.append(link); });
    document.getElementById('manual-search').addEventListener('input', event => { const query = event.target.value.toLowerCase().trim(); content.querySelectorAll('.manual-section').forEach(section => { section.hidden = query && !section.innerText.toLowerCase().includes(query); }); });
});
